import logging
import paramiko
import time

from hran_bsc.utils import is_bytes
from hran_bsc.connection_keeper import ConnectionUpkeeper


class SSHConnection(object):

    def __init__(self, host=None, port=22):
        self.host = host
        self.port = int(port) if port else 22
        self._read_timeout = 15.0
        self._encoding = (u'UTF-8', u'ignore')
        self.ssh_client = paramiko.SSHClient()
        self.ssh_client.set_missing_host_key_policy(paramiko.AutoAddPolicy())
        self.channel = None
        self.upkeeper = ConnectionUpkeeper(self)

    def open(self, host, usr=None, pwd=None, port=None, timeout=None):
        self.ssh_client.connect(hostname=host, port=int(port) if port else self.port, username=usr, password=pwd,
                                timeout=int(timeout) if timeout else None)
        self.channel = self.ssh_client.invoke_shell()

    def close(self):
        self.ssh_client.close()

    def read_until(self, match, timeout=None):
        timeout = timeout or self._read_timeout
        match = self._encode(match)
        delta = 0
        read_data = b''
        start = time.time()
        while delta <= timeout:
            delta = time.time() - start
            if self.sock_avail():
                read_data += self.channel.recv(1024)
            if match in read_data:
                return self._decode(read_data)
        return self._decode(read_data)

    def read_very_eager(self):
        read_data = b''
        timeout = 120
        start = time.time()
        while self.sock_avail() and not self.channel.closed:
            delta = time.time() - start
            if delta > timeout:
                logging.debug('Timeout expired (120s) at reading very eager data from SSH channel')
                break
            try:
                read_data += self.channel.recv(1024)
            except:  # noqa: E722
                break
        return self._decode(read_data)

    def read_all(self):
        return self.read_very_eager()

    def sock_avail(self):
        """Test whether data is available on the socket."""
        return self.channel.recv_ready()

    def write(self, buffer):
        buffer = self._encode(buffer)
        self.channel.send(buffer)

    def _encode(self, text):
        if is_bytes(text):
            return text
        if self._encoding[0] == 'NONE':
            return text.encode('ASCII')
        return text.encode(*self._encoding)

    def _decode(self, bytes):
        if self._encoding[0] == 'NONE':
            return bytes
        return bytes.decode(*self._encoding)

    def _set_encoding(self, encoding, errors):
        old = self._encoding
        encoding = encoding or old[0]
        errors = errors or old[1]
        self._encoding = (encoding.upper(), errors.lower())
